const src = $json.body || $json || {};
function pick(...names) {
  for (const name of names) {
    if (src[name] !== undefined && src[name] !== null && String(src[name]).trim() !== '') return src[name];
  }
  return '';
}
function norm(v) {
  return String(v || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toUpperCase();
}
const operationRaw = String(pick('Operacion', 'Operación', 'operacion', 'operation', 'field-0') || 'Preview impacto');
const operation = norm(operationRaw);
const selectorRaw = String(pick('Selector', 'selector_tipo', 'Selector tipo', 'selector', 'field-1') || 'telefonos');
const selectorType = norm(selectorRaw).replace(/\s+/g, '_').toLowerCase();
const valuesRaw = String(pick('Valores', 'Telefonos o IDs', 'telefonos_o_ids', 'values', 'field-2') || '');
const brandRaw = norm(pick('Marca', 'marca', 'field-3') || 'AMBAS');
const brand = ['KIA', 'HYUNDAI'].includes(brandRaw) ? brandRaw : '';
const limitRaw = Number.parseInt(String(pick('Limite', 'Límite', 'limit', 'field-4') || ''), 10);
const limit = Number.isInteger(limitRaw) && limitRaw > 0 ? Math.min(limitRaw, 100000) : 500;
const executeRaw = norm(pick('Ejecutar', 'execute', 'field-5') || 'NO');
// Bypass QA del bloqueo anti-duplicado de 6 horas. Solo tiene efecto en la
// zona de prueba controlada del panel web, que ya esta limitada a UN lead y
// exige confirmacion escrita.
const forceResend = ['1','SI','SÍ','TRUE','ON','FORZAR'].includes(norm(pick('ForzarReenvio', 'forzar_reenvio', 'force_resend') || ''));
const execute = ['SI', 'SÍ', 'TRUE', '1', 'EJECUTAR'].includes(executeRaw);
const requested = valuesRaw.split(/[\n,;\t]+/).map(v => v.trim()).filter(Boolean);
const allowedSelectors = new Set(['telefonos', 'telefono', 'phones', 'quicklink_ids', 'quicklink_id', 'ids', 'lead_ids', 'lead_id', 'marca', 'todos', 'todo']);

if (!allowedSelectors.has(selectorType)) {
  throw new Error('Selector inválido: ' + selectorRaw);
}

let action = 'preview';
const noDispatchRequested = operation.includes('SIN REENVIAR') || operation.includes('SIN ENVIAR') || operation.includes('NO REENVIAR') || operation.includes('NO ENVIAR');
if (operation.includes('BORRAR TODO') && operation.includes('REENVIAR') && !noDispatchRequested) action = 'cleanup_dispatch_all';
else if (operation.includes('BORRAR TODO')) action = 'cleanup_all';
else if (operation.includes('BORRAR') && operation.includes('REENVIAR') && !noDispatchRequested) action = 'cleanup_dispatch';
else if (operation.includes('BORRAR')) action = 'cleanup_only';
else if (operation.includes('ENVIAR')) action = 'dispatch_only';

const cleanup = action === 'cleanup_only' || action === 'cleanup_all' || action === 'cleanup_dispatch' || action === 'cleanup_dispatch_all';
const dispatch = action === 'dispatch_only' || action === 'cleanup_dispatch' || action === 'cleanup_dispatch_all';
const allTarget = action === 'cleanup_all' || action === 'cleanup_dispatch_all' || ['todos', 'todo'].includes(selectorType);
if (allTarget && !['cleanup_all', 'cleanup_dispatch_all'].includes(action)) {
  throw new Error('Selector TODOS solo está permitido con una operación BORRAR TODO');
}
if (!allTarget && selectorType !== 'marca' && !requested.length) {
  throw new Error('Debe ingresar al menos un teléfono o quicklink_id, o usar selector por marca/todos');
}
if (selectorType === 'marca' && !brand) {
  throw new Error('El selector MARCA requiere elegir KIA o HYUNDAI');
}
if (['quicklink_ids', 'quicklink_id', 'ids'].includes(selectorType)) {
  if (!brand) throw new Error('Los quicklink_ids requieren una marca específica para evitar colisiones');
  const invalid = requested.find(v => !/^\d{1,9}$/.test(v));
  if (invalid) throw new Error('quicklink_id inválido: ' + invalid);
}
if (['lead_ids', 'lead_id'].includes(selectorType)) {
  const invalid = requested.find(v => !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(v));
  if (invalid) throw new Error('lead_id UUID inválido: ' + invalid);
}
if (['telefonos', 'telefono', 'phones'].includes(selectorType)) {
  const invalid = requested.find(v => {
    const digits = v.replace(/\D/g, '');
    return digits.length < 9 || digits.length > 15;
  });
  if (invalid) throw new Error('Teléfono inválido; se requieren entre 9 y 15 dígitos: ' + invalid);
}

let confirmationRequired = execute && (cleanup || dispatch);
const expectedConfirmation = action === 'cleanup_dispatch_all'
  ? 'BORRAR TODO'
  : action === 'cleanup_all'
    ? 'BORRAR TODO'
    : cleanup
      ? 'BORRAR'
      : dispatch
        ? 'ENVIAR'
        : '';

const viaWebhook = ['1', 'true', 'si', 'yes'].includes(String(pick('via_webhook') || '').toLowerCase());
if (viaWebhook) {
  const WEB_TOKEN = 'QLpanel-x9f3-2026';
  if (String(pick('_k') || '') !== WEB_TOKEN) throw new Error('Acceso web no autorizado');
  if (execute && (cleanup || dispatch)) {
    const exactLeadSelector = ['lead_ids', 'lead_id'].includes(selectorType);
    const exactLeadValue = requested.length === 1 && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(requested[0]);
    if (!exactLeadSelector || !exactLeadValue || limit !== 1 || allTarget) {
      throw new Error('Ejecución web limitada a un único lead_id, selector lead_ids y limite 1');
    }
  }
  if (confirmationRequired) {
    const direct = norm(pick('Confirmacion', 'confirmacion', 'Confirmación') || '');
    if (direct !== norm(expectedConfirmation)) throw new Error('Confirmación inválida: escriba ' + expectedConfirmation);
    confirmationRequired = false;
  }
}

return [{ json: {
  operation_label: operationRaw,
  action,
  selector_type: allTarget ? 'todos' : (selectorType === 'lead_id' ? 'lead_ids' : selectorType),
  requested_values: requested,
  brand,
  limit,
  execute,
  dry_run: !execute,
  cleanup,
  dispatch,
  confirmation_required: confirmationRequired,
  expected_confirmation: expectedConfirmation,
  via_webhook: viaWebhook,
  force_resend: forceResend,
  requested_by: viaWebhook ? 'panel-web' : 'panel-operador',
} }];

const cfg = $('Preparar').first().json;
const row = $input.first().json || {};
const impact = row.impact || {};
const leads = Array.isArray(row.leads) ? row.leads : [];
const chatwoot = Array.isArray(row.chatwoot_conv_ids) ? row.chatwoot_conv_ids : [];

if (cfg.via_webhook && cfg.execute && (cfg.cleanup || cfg.dispatch)) {
  const requestedLeadIds = Array.isArray(cfg.requested_values) ? cfg.requested_values.map(v => String(v || '').trim().toLowerCase()).filter(Boolean) : [];
  const requestedLeadId = requestedLeadIds[0] || '';
  const exactLeadRequest = cfg.selector_type === 'lead_ids' && requestedLeadIds.length === 1 && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(requestedLeadId) && Number(cfg.limit) === 1;
  if (!exactLeadRequest) {
    throw new Error('Ejecución web rechazada: se requiere un único lead_id exacto y limite 1');
  }
  if (leads.length !== 1 || String(leads[0].lead_id || '').toLowerCase() !== requestedLeadId) {
    throw new Error('Ejecución web rechazada: el lead_id solicitado debe resolver exactamente 1 lead, recibidos ' + leads.length);
  }
}

const recentOutboundBlocks = Array.isArray(row.recent_outbound_blocks) ? row.recent_outbound_blocks : [];

// El bypass solo aplica si el operador lo marco explicitamente. Se deja
// constancia en el resultado para que quede rastro de que se forzo.
if (cfg.via_webhook && cfg.execute && cfg.dispatch && !cfg.force_resend && recentOutboundBlocks.length) {
  const firstBlock = recentOutboundBlocks[0] || {};
  throw new Error('Reenvio web bloqueado: ya existe outbound reciente para este lead (' + (firstBlock.batch_key || firstBlock.request_id || 'sin batch') + ', estado=' + (firstBlock.delivery_status || firstBlock.intake_status || 'desconocido') + ').');
}
if (cfg.execute && !leads.length) {
  throw new Error('Ejecución cancelada: ningún lead coincide exactamente con los criterios');
}
const dispatchable = leads.filter(lead => {
  const digits = String(lead.telefono_agente || '').replace(/\D/g, '');
  return digits.length >= 9 && digits.length <= 15;
});
const skippedForAgentPhone = leads.length - dispatchable.length;

const lines = [];
lines.push(`Operación: ${cfg.operation_label}`);
lines.push(`Modo: ${cfg.execute ? 'EJECUCIÓN REAL' : 'DRY-RUN / PREVIEW'}`);
lines.push(`Targets: ${leads.length} lead(s), ${impact.conversations || 0} conversación(es), ${chatwoot.length} conversación(es) Chatwoot.`);
if (impact.excluded_non_pending) lines.push(`Excluidos por no estar PENDIENTE: ${impact.excluded_non_pending}.`);
if (cfg.dispatch && skippedForAgentPhone) lines.push(`Sin envío por TELEFONO AGENTE inválido/vacío: ${skippedForAgentPhone}.`);
lines.push(`Memoria: lead_memory=${impact.lead_memory || 0}, n8n_chat_histories=${impact.n8n_chat_histories || 0}, redis_buffers=${impact.redis_buffer_keys || 0}.`);
lines.push(`Runtime: followups=${impact.scheduled_followups || 0}, interactions=${impact.conversation_interactions || 0}, wa_events=${impact.whatsapp_interaction_events || 0}, context=${impact.conversation_context || 0}, campaign_queue=${impact.lead_campaign_queue || 0}, agent_decisions=${impact.agent_decisions || 0}, eventos=${impact.events || 0}, handoffs=${impact.handoffs || 0}.`);
lines.push('');
lines.push('Leads:');
for (const lead of leads.slice(0, 25)) {
  lines.push(`- ${lead.marca} #${lead.quicklink_id} ${lead.nombre_cliente || ''} agente:${lead.telefono_agente || 'sin telefono'} ${lead.modelo || ''}`.trim());
}
if (leads.length > 25) lines.push(`- ... ${leads.length - 25} más`);

return [{ json: { ...cfg, ...row, preview_message: lines.join('\n') } }];

