parameters.jsCode:
const cfg = $('Preparar').first().json;
const impact = $('Format Preview').first().json;
const src = $json.body || $json || {};
const raw = String(src.Confirmacion || src.confirmacion || src.Confirmación || src['field-0'] || '').trim().toUpperCase();
const ok = raw === String(cfg.expected_confirmation || '').toUpperCase();
return [{ json: { ...cfg, ...impact, confirmation_value: raw, confirmed: ok } }];

const cfg = $('Preparar').first().json;
const row = $('Format Preview').first().json;
const ids = [...new Set(Array.isArray(row.chatwoot_conv_ids) ? row.chatwoot_conv_ids.map(Number).filter(Boolean) : [])];
const dryRun = !cfg.execute || !cfg.cleanup;
const baseUrl = 'http://chatwoot:3000';
const token = 'MxVixgmtgZaoKVSarHdWyv1W';
const accountId = 2;
const results = [];

for (const id of ids) {
  if (dryRun) {
    results.push({ id, action: 'dry_run_delete_conversation', ok: true });
    continue;
  }
  try {
    const resp = await this.helpers.httpRequest({
      method: 'DELETE',
      url: `${baseUrl}/api/v1/accounts/${accountId}/conversations/${id}`,
      headers: { api_access_token: token, 'Content-Type': 'application/json' },
      ignoreHttpStatusErrors: true,
      returnFullResponse: true,
      timeout: 30000,
    });
    const statusCode = resp.statusCode || resp.status || 0;
    const ok = (statusCode >= 200 && statusCode < 300) || statusCode === 404;
    results.push({
      id,
      action: statusCode === 404 ? 'already_absent' : 'delete_conversation',
      ok,
      statusCode,
    });
  } catch (e) {
    results.push({ id, action: 'delete_conversation', ok: false, error: String(e.message || e).slice(0, 300) });
  }
}

const deleted = results.filter(r => r.ok && r.action === 'delete_conversation').length;
const alreadyAbsent = results.filter(r => r.ok && r.action === 'already_absent').length;
const failedResults = results.filter(r => !r.ok);
if (!dryRun && failedResults.length) {
  const detail = failedResults.map(r => `${r.id}:${r.statusCode || r.error || 'error'}`).join(', ');
  throw new Error(`Chatwoot cleanup falló para ${failedResults.length} conversación(es): ${detail}`);
}

return [{
  json: {
    ...row,
    chatwoot_delete: {
      dry_run: dryRun,
      targeted: ids.length,
      deleted,
      already_absent: alreadyAbsent,
      failed: failedResults.length,
      results,
    },
  },
}];

parameters.query:
SET search_path TO sales_prod, public, extensions;
DROP TABLE IF EXISTS pg_temp._panel_leads;
DROP TABLE IF EXISTS pg_temp._panel_convs;
DROP TABLE IF EXISTS pg_temp._panel_sessions;
DROP TABLE IF EXISTS pg_temp._panel_phone_aliases;
DROP TABLE IF EXISTS pg_temp._panel_counts;
DROP TABLE IF EXISTS pg_temp._panel_residuals;

CREATE TEMP TABLE _panel_leads(
  id uuid PRIMARY KEY,
  quicklink_id integer,
  phone1_digits text,
  phone2_digits text,
  agent_phone_digits text
) ON COMMIT DROP;
CREATE TEMP TABLE _panel_convs(id uuid PRIMARY KEY) ON COMMIT DROP;
CREATE TEMP TABLE _panel_sessions(session_id text PRIMARY KEY) ON COMMIT DROP;
CREATE TEMP TABLE _panel_phone_aliases(digits text PRIMARY KEY) ON COMMIT DROP;
CREATE TEMP TABLE _panel_counts(seq serial, table_name text, action text, affected integer) ON COMMIT DROP;
CREATE TEMP TABLE _panel_residuals(seq serial, table_name text, residual integer) ON COMMIT DROP;

INSERT INTO _panel_leads(id, quicklink_id, phone1_digits, phone2_digits, agent_phone_digits)
SELECT
  lead.lead_id::uuid,
  lead.quicklink_id,
  NULLIF(regexp_replace(COALESCE(lead.telefono_1, ''), '\D', '', 'g'), ''),
  NULLIF(regexp_replace(COALESCE(lead.telefono_2, ''), '\D', '', 'g'), ''),
  NULLIF(regexp_replace(COALESCE(lead.telefono_agente, ''), '\D', '', 'g'), '')
FROM jsonb_to_recordset($1::jsonb) AS lead(
  lead_id text,
  quicklink_id integer,
  telefono_1 text,
  telefono_2 text,
  telefono_agente text
)
WHERE lead.lead_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
ON CONFLICT DO NOTHING;

INSERT INTO _panel_convs(id)
SELECT value::uuid FROM jsonb_array_elements_text($2::jsonb) value
WHERE value ~* '^[0-9a-f-]{36}$'
ON CONFLICT DO NOTHING;

INSERT INTO _panel_sessions(session_id)
SELECT value FROM jsonb_array_elements_text($3::jsonb) value
WHERE NULLIF(value, '') IS NOT NULL
ON CONFLICT DO NOTHING;

INSERT INTO _panel_phone_aliases(digits)
SELECT DISTINCT NULLIF(regexp_replace(value, '\D', '', 'g'), '')
FROM jsonb_array_elements_text($4::jsonb) value
WHERE NULLIF(regexp_replace(value, '\D', '', 'g'), '') IS NOT NULL
ON CONFLICT DO NOTHING;

INSERT INTO _panel_phone_aliases(digits)
SELECT DISTINCT digits
FROM _panel_leads l
CROSS JOIN LATERAL (VALUES
  (l.phone1_digits),
  (l.phone2_digits),
  (l.agent_phone_digits),
  (CASE WHEN l.phone1_digits ~ '^0\d{9}$' THEN '593' || substring(l.phone1_digits FROM 2) END),
  (CASE WHEN l.phone2_digits ~ '^0\d{9}$' THEN '593' || substring(l.phone2_digits FROM 2) END),
  (CASE WHEN l.agent_phone_digits ~ '^0\d{9}$' THEN '593' || substring(l.agent_phone_digits FROM 2) END),
  (CASE WHEN l.phone1_digits ~ '^9\d{8}$' THEN '593' || l.phone1_digits END),
  (CASE WHEN l.phone2_digits ~ '^9\d{8}$' THEN '593' || l.phone2_digits END),
  (CASE WHEN l.agent_phone_digits ~ '^9\d{8}$' THEN '593' || l.agent_phone_digits END),
  (CASE WHEN length(l.phone1_digits) >= 9 THEN right(l.phone1_digits, 9) END),
  (CASE WHEN length(l.phone2_digits) >= 9 THEN right(l.phone2_digits, 9) END),
  (CASE WHEN length(l.agent_phone_digits) >= 9 THEN right(l.agent_phone_digits, 9) END)
) aliases(digits)
WHERE NULLIF(digits, '') IS NOT NULL
ON CONFLICT DO NOTHING;

CREATE OR REPLACE FUNCTION pg_temp.panel_table_schema(p_table text)
RETURNS text
LANGUAGE sql
STABLE
AS $fn$
  SELECT table_schema
  FROM information_schema.tables
  WHERE table_schema IN ('sales_prod', 'public')
    AND table_name = p_table
  ORDER BY CASE table_schema WHEN 'sales_prod' THEN 1 WHEN 'public' THEN 2 ELSE 3 END
  LIMIT 1;
$fn$;

CREATE OR REPLACE FUNCTION pg_temp.panel_table_exists(p_table text)
RETURNS boolean
LANGUAGE sql
STABLE
AS $fn$
  SELECT pg_temp.panel_table_schema(p_table) IS NOT NULL;
$fn$;

CREATE OR REPLACE FUNCTION pg_temp.panel_col_exists(p_table text, p_col text)
RETURNS boolean
LANGUAGE sql
STABLE
AS $fn$
  SELECT EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_schema = pg_temp.panel_table_schema(p_table)
      AND table_name = p_table
      AND column_name = p_col
  );
$fn$;

CREATE OR REPLACE FUNCTION pg_temp.panel_phone_match(p_value text)
RETURNS boolean
LANGUAGE sql
STABLE
AS $fn$
  WITH d AS (
    SELECT NULLIF(regexp_replace(COALESCE(p_value, ''), '\D', '', 'g'), '') AS digits
  )
  SELECT EXISTS (
    SELECT 1
    FROM d, _panel_phone_aliases a
    WHERE d.digits IS NOT NULL
      AND a.digits IS NOT NULL
      AND length(d.digits) >= 9
      AND length(a.digits) >= 9
      AND (
        d.digits = a.digits
        OR right(d.digits, 9) = right(a.digits, 9)
        OR d.digits LIKE '%' || a.digits
        OR a.digits LIKE '%' || d.digits
      )
  );
$fn$;

CREATE OR REPLACE FUNCTION pg_temp.panel_apply_delete(
  p_table text,
  p_action text,
  p_condition text
)
RETURNS integer
LANGUAGE plpgsql
AS $fn$
DECLARE
  v_count integer := 0;
  v_schema text;
BEGIN
  v_schema := pg_temp.panel_table_schema(p_table);
  IF v_schema IS NULL OR COALESCE(p_condition, '') = '' THEN
    v_count := 0;
  ELSE
    EXECUTE format(
      'WITH deleted AS (DELETE FROM %I.%I t WHERE %s RETURNING 1) SELECT count(*)::integer FROM deleted',
      v_schema,
      p_table,
      p_condition
    ) INTO v_count;
  END IF;

  INSERT INTO _panel_counts(table_name, action, affected)
  VALUES (p_table, p_action, COALESCE(v_count, 0));
  RETURN COALESCE(v_count, 0);
END;
$fn$;

CREATE OR REPLACE FUNCTION pg_temp.panel_residual(
  p_table text,
  p_condition text
)
RETURNS integer
LANGUAGE plpgsql
AS $fn$
DECLARE
  v_count integer := 0;
  v_schema text;
BEGIN
  v_schema := pg_temp.panel_table_schema(p_table);
  IF v_schema IS NULL OR COALESCE(p_condition, '') = '' THEN
    v_count := 0;
  ELSE
    EXECUTE format('SELECT count(*)::integer FROM %I.%I t WHERE %s', v_schema, p_table, p_condition)
      INTO v_count;
  END IF;

  INSERT INTO _panel_residuals(table_name, residual)
  VALUES (p_table, COALESCE(v_count, 0));
  RETURN COALESCE(v_count, 0);
END;
$fn$;

DO $do$
DECLARE
  n integer;
  conds text[];
  cond text;
  set_list text[];
  target_schema text;
BEGIN
  IF pg_temp.panel_table_exists('scheduled_followups') THEN
    conds := ARRAY[]::text[];
    IF pg_temp.panel_col_exists('scheduled_followups', 'conversation_id') THEN conds := array_append(conds, 't.conversation_id IN (SELECT id FROM _panel_convs)'); END IF;
    IF pg_temp.panel_col_exists('scheduled_followups', 'phone') THEN conds := array_append(conds, 'pg_temp.panel_phone_match(t.phone::text)'); END IF;
    PERFORM pg_temp.panel_apply_delete('scheduled_followups', 'delete', array_to_string(conds, ' OR '));
  END IF;

  IF pg_temp.panel_table_exists('conversation_interactions') THEN
    PERFORM pg_temp.panel_apply_delete('conversation_interactions', 'delete', 't.conversation_id IN (SELECT id FROM _panel_convs)');
  END IF;

  IF pg_temp.panel_table_exists('whatsapp_interaction_events') THEN
    conds := ARRAY[]::text[];
    IF pg_temp.panel_col_exists('whatsapp_interaction_events', 'conversation_id') THEN conds := array_append(conds, 't.conversation_id IN (SELECT id FROM _panel_convs)'); END IF;
    IF pg_temp.panel_col_exists('whatsapp_interaction_events', 'phone') THEN conds := array_append(conds, 'pg_temp.panel_phone_match(t.phone::text)'); END IF;
    PERFORM pg_temp.panel_apply_delete('whatsapp_interaction_events', 'delete', array_to_string(conds, ' OR '));
  END IF;

  IF pg_temp.panel_table_exists('agent_decisions') THEN
    PERFORM pg_temp.panel_apply_delete('agent_decisions', 'delete', 't.conversation_id IN (SELECT id FROM _panel_convs)');
  END IF;

  IF pg_temp.panel_table_exists('conversation_memory') THEN
    PERFORM pg_temp.panel_apply_delete('conversation_memory', 'delete', 't.conversation_id IN (SELECT id FROM _panel_convs)');
  END IF;

  IF pg_temp.panel_table_exists('datos_calificacion') THEN
    PERFORM pg_temp.panel_apply_delete('datos_calificacion', 'delete', 't.conversation_id IN (SELECT id FROM _panel_convs)');
  END IF;

  IF pg_temp.panel_table_exists('transferencias_humano') THEN
    conds := ARRAY[]::text[];
    IF pg_temp.panel_col_exists('transferencias_humano', 'conversation_id') THEN conds := array_append(conds, 't.conversation_id IN (SELECT id FROM _panel_convs)'); END IF;
    IF pg_temp.panel_col_exists('transferencias_humano', 'conversacion_id') THEN conds := array_append(conds, 't.conversacion_id IN (SELECT id FROM _panel_convs)'); END IF;
    IF pg_temp.panel_col_exists('transferencias_humano', 'lead_id') THEN conds := array_append(conds, 't.lead_id IN (SELECT id FROM _panel_leads)'); END IF;
    IF pg_temp.panel_col_exists('transferencias_humano', 'telefono') THEN conds := array_append(conds, 'pg_temp.panel_phone_match(t.telefono::text)'); END IF;
    PERFORM pg_temp.panel_apply_delete('transferencias_humano', 'delete', array_to_string(conds, ' OR '));
  END IF;

  IF pg_temp.panel_table_exists('eventos_conversacion') THEN
    conds := ARRAY[]::text[];
    IF pg_temp.panel_col_exists('eventos_conversacion', 'conversation_id') THEN conds := array_append(conds, 't.conversation_id IN (SELECT id FROM _panel_convs)'); END IF;
    IF pg_temp.panel_col_exists('eventos_conversacion', 'conversacion_id') THEN conds := array_append(conds, 't.conversacion_id IN (SELECT id FROM _panel_convs)'); END IF;
    PERFORM pg_temp.panel_apply_delete('eventos_conversacion', 'delete', array_to_string(conds, ' OR '));
  END IF;

  IF pg_temp.panel_table_exists('intentos_contacto') THEN
    conds := ARRAY[]::text[];
    IF pg_temp.panel_col_exists('intentos_contacto', 'conversation_id') THEN conds := array_append(conds, 't.conversation_id IN (SELECT id FROM _panel_convs)'); END IF;
    IF pg_temp.panel_col_exists('intentos_contacto', 'conversacion_id') THEN conds := array_append(conds, 't.conversacion_id IN (SELECT id FROM _panel_convs)'); END IF;
    PERFORM pg_temp.panel_apply_delete('intentos_contacto', 'delete', array_to_string(conds, ' OR '));
  END IF;

  IF pg_temp.panel_table_exists('conversation_context') THEN
    conds := ARRAY[]::text[];
