const cfg = $('Preparar').first().json;
const preview = $('Format Preview').first().json;
const chatwoot = $('Borrar Chatwoot Conversaciones').first().json.chatwoot_delete || {};
const trackingNode = $('Abrir Tracking Outbound').first().json || {};
const inputItems = $input.all();
const redisKeys = inputItems
  .map(item => item.json.redis_key)
  .filter(key => key && key !== '__cris_panel_noop__');
const leads = Array.isArray(preview.leads) ? preview.leads : [];
const shouldDispatch = cfg.execute && cfg.dispatch;
const outboundUrls = [
  'http://localhost:5678/webhook/quicklink-lead-inbound',
];
const outboundHeaders = { 'Content-Type': 'application/json', 'x-ql-sync-token': '0211fb62410106c2d4884f3131fd219390ded7d87a8f46e2' };
const delay = ms => new Promise(resolve => setTimeout(resolve, ms));
const tracking = trackingNode.outbound_tracking || {};
const trackedDispatches = Array.isArray(tracking.dispatches) ? tracking.dispatches : [];
const requestByLead = new Map(trackedDispatches.map(row => [String(row.lead_id), row.request_id]));
const results = [];

const retryableStatus = statusCode => statusCode === 0 || statusCode === 404 || statusCode === 408 || statusCode === 429 || statusCode >= 500;
const parseResponseBody = body => {
  if (typeof body !== 'string') return body || {};
  try { return JSON.parse(body); } catch (e) { return {}; }
};
const postOutbound = async payload => {
  const attempts = [];
  for (const outboundUrl of outboundUrls) {
    try {
      const resp = await this.helpers.httpRequest({
        method: 'POST',
        url: outboundUrl,
        headers: outboundHeaders,
        body: JSON.stringify(payload),
        timeout: 30000,
        ignoreHttpStatusErrors: true,
        returnFullResponse: true,
      });
      const statusCode = resp.statusCode || resp.status || 0;
      const responseBody = parseResponseBody(resp.body || {});
      const accepted = statusCode === 202 && responseBody?.accepted === true;
      const error = accepted ? null : String(responseBody?.message || responseBody?.error || `HTTP ${statusCode}`).slice(0, 300);
      attempts.push({ url: outboundUrl, statusCode, accepted, error });
      if (accepted || !retryableStatus(statusCode)) {
        return { accepted, statusCode, error, outbound_url: outboundUrl, attempts };
      }
    } catch (e) {
      attempts.push({ url: outboundUrl, statusCode: 0, accepted: false, error: String(e.message || e).slice(0, 300) });
    }
  }
  const last = attempts[attempts.length - 1] || {};
  return {
    accepted: false,
    statusCode: last.statusCode || 0,
    error: String(last.error || 'outbound_unavailable').slice(0, 300),
    outbound_url: last.url || null,
    attempts,
  };
};

for (const lead of leads) {
  const agentPhone = String(lead.telefono_agente || '').trim();
  const agentDigits = agentPhone.replace(/\D/g, '');
  if (agentDigits.length < 9 || agentDigits.length > 15) {
    results.push({
      lead_id: lead.lead_id,
      quicklink_id: lead.quicklink_id,
      marca: lead.marca,
      request_id: null,
      status: 'skipped',
      error: agentPhone ? 'invalid_agent_phone' : 'missing_agent_phone',
    });
    continue;
  }
  const requestId = requestByLead.get(String(lead.lead_id)) || null;
  const payload = {
    phone: agentPhone,
    marca: lead.marca,
    quicklink_id: lead.quicklink_id,
    lead_id: lead.lead_id,
    nombre_cliente: lead.nombre_cliente,
    modelo: lead.modelo,
    source: 'panel-operador',
    batch_key: tracking.batch_key || null,
    request_id: requestId,
  };
  if (!shouldDispatch) {
    results.push({
      lead_id: lead.lead_id,
      quicklink_id: lead.quicklink_id,
      marca: lead.marca,
      request_id: requestId,
      status: cfg.dispatch ? 'dry_run' : 'not_requested',
    });
    continue;
  }
  if (!requestId) {
    results.push({
      lead_id: lead.lead_id,
      quicklink_id: lead.quicklink_id,
      marca: lead.marca,
      request_id: null,
      status: 'failed',
      error: 'tracking_request_id_missing',
    });
    continue;
  }
  const outbound = await postOutbound(payload);
  results.push({
    lead_id: lead.lead_id,
    quicklink_id: lead.quicklink_id,
    marca: lead.marca,
    request_id: requestId,
    status: outbound.accepted ? 'accepted' : (outbound.statusCode ? 'rejected' : 'failed'),
    statusCode: outbound.statusCode,
    outbound_url: outbound.outbound_url,
    outbound_attempts: outbound.attempts,
    error: outbound.accepted ? null : outbound.error,
  });
  await delay(750);
}

const accepted = results.filter(r => r.status === 'accepted').length;
const failed = results.filter(r => r.status === 'failed' || r.status === 'rejected').length;
const skipped = results.filter(r => r.status === 'skipped').length;
return [{
  json: {
    ...preview,
    chatwoot_delete: chatwoot,
    cleanup_counts: Array.isArray(trackingNode.cleanup_counts) ? trackingNode.cleanup_counts : [],
    residual_counts: Array.isArray(trackingNode.residual_counts) ? trackingNode.residual_counts : [],
    outbound_tracking: tracking,
    redis_deleted_keys: redisKeys,
    dispatch_result: {
      requested: cfg.dispatch,
      executed: shouldDispatch,
      accepted,
      failed,
      skipped,
      results,
    },
  },
}];

const input = $input.first().json || {};
const preview = $('Format Preview').first().json;
const chatwoot = $('Borrar Chatwoot Conversaciones').first().json.chatwoot_delete || {};
const row = {
  ...preview,
  chatwoot_delete: chatwoot,
  cleanup_counts: Array.isArray(input.cleanup_counts) ? input.cleanup_counts : [],
  residual_counts: Array.isArray(input.residual_counts) ? input.residual_counts : [],
  outbound_tracking: input.outbound_tracking || {},
};
const shouldDeleteRedis = row.execute === true && row.cleanup === true;
let keys = [];
if (shouldDeleteRedis) {
  keys = [...new Set(Array.isArray(row.redis_keys) ? row.redis_keys.filter(Boolean) : [])];
}
if (!keys.length) keys.push('__cris_panel_noop__');

return keys.map((redis_key, index) => ({
  json: {
    redis_key,
    _redis_index: index,
    _redis_total: keys.length,
    redis_delete_executed: shouldDeleteRedis && redis_key !== '__cris_panel_noop__',
  },
}));

const base = $('Dispatch Outbound').first().json || $input.first().json || {};
const impact = base.impact || {};
const dispatch = base.dispatch_result || {};
const chatwoot = base.chatwoot_delete || {};
const tracking = base.outbound_tracking || {};
const cleanupCounts = Array.isArray(base.cleanup_counts) ? base.cleanup_counts : [];
const residualCounts = Array.isArray(base.residual_counts) ? base.residual_counts : [];
const redisKeys = Array.isArray(base.redis_deleted_keys) ? base.redis_deleted_keys : [];

const executed = !!base.execute;
const cleanup = !!base.cleanup;
const leadsCount = (base.leads || []).length;
const chatHist = impact.n8n_chat_histories || 0;
const dbRows = cleanupCounts.filter(c => (c.affected || 0) > 0);
const dbZero = cleanupCounts.length - dbRows.length;
const accepted = dispatch.accepted || 0;
const failed = dispatch.failed || 0;
const skipped = dispatch.skipped || 0;
const chatwootFailed = chatwoot.failed || 0;
const residualFailed = residualCounts.reduce((sum, r) => sum + (Number(r.residual || 0) > 0 ? 1 : 0), 0);
const totalFailed = failed + chatwootFailed + residualFailed;
const hasTracking = Boolean(tracking.batch_key && tracking.status_token);

const opLabel = base.operation_label || 'Operacion';
const status = !executed ? 'preview' : (totalFailed > 0 ? 'warning' : 'success');
const statusLabel = !executed ? 'Preview completado' : (totalFailed > 0 ? 'Completado con alertas' : 'Operacion completada');
const title = !executed
  ? `Preview - ${opLabel}`
  : (totalFailed > 0 ? `${opLabel} - revisar alertas` : `${opLabel} - listo`);

const lines = [];
lines.push(executed ? 'Ejecucion completada.' : 'Preview / dry-run completado.');
lines.push(`Operacion: ${opLabel}`);
lines.push(`Leads objetivo: ${leadsCount}`);
if (cleanup) {
  lines.push(`Chatwoot: borradas=${chatwoot.deleted || 0}, ya ausentes=${chatwoot.already_absent || 0}, fallidas=${chatwootFailed}`);
  lines.push(`Redis buffers eliminados: ${redisKeys.length}`);
  lines.push(`n8n_chat_histories: ${chatHist}`);
  if (residualCounts.length) lines.push(`Residuales post-cleanup: ${residualFailed ? residualFailed + ' tabla(s) con residuos' : '0'}`);
}
if (dbRows.length) lines.push(`DB cleanup: ${dbRows.map(c => `${c.table}:${c.affected}`).join(', ')}`);
if (dispatch.requested) lines.push(`Outbound intake: aceptados=${accepted}, fallidos=${failed}, omitidos_sin_agente=${skipped}, entrega=seguimiento Meta`);
if (tracking.batch_key) lines.push(`Tracking batch: ${tracking.batch_key}`);
if (!executed) lines.push('Para ejecutar realmente, vuelva al formulario con Ejecutar=SI y confirme el token indicado.');

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const metric = (label, value, hint, tone = '') => `<div class="ql-metric ${tone}"><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(hint || '')}</small></div>`;
const row = (label, value, strong) => `<div class="ql-row"><span>${esc(label)}</span><b class="${strong ? 'warn' : ''}">${esc(value)}</b></div>`;
const section = (name, body, cls = '') => body ? `<section class="ql-section ${cls}"><h2>${esc(name)}</h2>${body}</section>` : '';

let opBody = '';
opBody += row('Modo', executed ? 'Ejecucion real' : 'Preview / dry-run');
opBody += row('Leads objetivo', leadsCount);
if (impact.excluded_non_pending) opBody += row('Excluidos no pendientes', impact.excluded_non_pending, true);

let cleanBody = '';
if (cleanup) {
  cleanBody += row('Chatwoot eliminadas', chatwoot.deleted || 0);
  cleanBody += row('Chatwoot ya ausentes', chatwoot.already_absent || 0);
  cleanBody += row('Chatwoot fallidas', chatwootFailed, chatwootFailed > 0);
  cleanBody += row('Redis buffers eliminados', redisKeys.length);
  cleanBody += row('Memoria n8n_chat_histories', chatHist);
}

let dbBody = '';
for (const c of dbRows) dbBody += row(c.table, `${c.affected} fila(s)`);
if (dbRows.length && dbZero > 0) dbBody += `<p class="ql-muted">+ ${dbZero} tabla(s) sin filas afectadas</p>`;
if (!dbRows.length && cleanupCounts.length) dbBody = `<p class="ql-muted">Sin filas afectadas en ${cleanupCounts.length} tabla(s)</p>`;

let residualBody = '';
if (cleanup && residualCounts.length) {
  for (const r of residualCounts) residualBody += row(r.table, `${r.residual || 0} residual(es)`, Number(r.residual || 0) > 0);
}

let outBody = '';
if (dispatch.requested) {
  outBody += row('Aceptados por intake', accepted);
  outBody += row('Rechazados / fallidos', failed, failed > 0);
  outBody += row('Omitidos sin agente válido', skipped, skipped > 0);
  outBody += row('Entrega Meta', tracking.batch_key ? 'En seguimiento' : 'Sin tracking');
}

const panelBase = '/webhook/cris09-panel?k=QLpanel-x9f3-2026';
const searchUrl = `${panelBase}&operacion=${encodeURIComponent('Preview impacto')}&selector=todos&marca=AMBAS&limite=100000`;
const sendMoreUrl = `${panelBase}&operacion=${encodeURIComponent('Enviar pendientes seleccionados')}&selector=todos&marca=AMBAS&limite=100000`;
