const TOKEN = 'QLpanel-x9f3-2026';
const q = $json.query || {};
const clean = (v, max = 160) => String(v ?? '').trim().slice(0, max);

const k = clean(q.k, 80);
if (k !== TOKEN) {
  return [{ json: {
    authorized: false,
    error: 'forbidden',
    message: 'Acceso no autorizado: falta o es invalido el parametro k',
  } }];
}

const norm = (v) => clean(v, 120).normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toUpperCase();
const rawValues = clean(q.valores ?? q.valor ?? '', 3000);
const requested = rawValues.split(/[\n,;\t]+/).map((v) => clean(v, 160)).filter(Boolean).slice(0, 100);

const OPS = [
  'Preview impacto',
  'Enviar pendientes seleccionados',
  'Borrar seleccionados',
  'Borrar TODO sin enviar',
  'Borrar + reenviar seleccionados',
  'Borrar TODO + reenviar TODO',
];
const operationRaw = clean(q.operacion, 80) || 'Preview impacto';
const operationNorm = norm(operationRaw);
const operationMatched = OPS.find((op) => norm(op) === operationNorm);
const operacion = operationMatched || 'Preview impacto';

let action = 'preview';
const noDispatchRequested = operationNorm.includes('SIN REENVIAR') || operationNorm.includes('SIN ENVIAR') || operationNorm.includes('NO REENVIAR') || operationNorm.includes('NO ENVIAR');
if (operationNorm.includes('BORRAR TODO') && operationNorm.includes('REENVIAR') && !noDispatchRequested) action = 'cleanup_dispatch_all';
else if (operationNorm.includes('BORRAR TODO')) action = 'cleanup_all';
else if ((operationNorm.includes('BORRAR') || operationNorm.includes('RESET')) && operationNorm.includes('REENVIAR') && !noDispatchRequested) action = 'cleanup_dispatch';
else if (operationNorm.includes('BORRAR') || operationNorm.includes('RESET')) action = 'cleanup_only';
else if (operationNorm.includes('ENVIAR')) action = 'dispatch_only';

const selectorAliases = {
  inteligente: 'smart',
  buscar: 'smart',
  cliente: 'nombre',
  clientes: 'nombre',
  nombres: 'nombre',
  telefono: 'telefonos',
  phone: 'telefonos',
  phones: 'telefonos',
  quicklink_id: 'quicklink_ids',
  qlid: 'quicklink_ids',
  id: 'quicklink_ids',
  ids: 'quicklink_ids',
  lead_id: 'lead_ids',
  uuid: 'lead_ids',
  todo: 'todos',
  all: 'todos',
};
const selectorInput = clean(q.selector, 30).toLowerCase();
const selector = selectorAliases[selectorInput] || selectorInput || 'smart';
const allowedSelectors = ['smart', 'nombre', 'telefonos', 'quicklink_ids', 'lead_ids', 'marca', 'todos'];

const marcaRaw = norm(q.marca || 'AMBAS');
const marca = ['KIA', 'HYUNDAI'].includes(marcaRaw) ? marcaRaw : '';
const marca_sel = marca || 'AMBAS';

const estados = ['PENDIENTE', 'REZAGADO', 'EN_GESTION', 'GESTION_PERDIDA', 'CONFIRMADA_AI', 'SIN_ESTADO'];
const estadoRaw = norm(q.estado || '');
const estado = estados.includes(estadoRaw) ? estadoRaw : '';

const dateRawDesde = clean(q.desde, 10);
const dateRawHasta = clean(q.hasta, 10);
const validDate = (v) => /^\d{4}-\d{2}-\d{2}$/.test(v) && !Number.isNaN(new Date(v + 'T00:00:00Z').getTime());
const desde = dateRawDesde && validDate(dateRawDesde) ? dateRawDesde : '';
const hasta = dateRawHasta && validDate(dateRawHasta) ? dateRawHasta : '';

const sizeRaw = Number.parseInt(clean(q.page_size || q.limite, 5), 10);
const page_size = Number.isInteger(sizeRaw) && sizeRaw > 0 ? Math.min(Math.max(sizeRaw, 25), 250) : 25;
const pageRaw = Number.parseInt(clean(q.page, 7), 10);
const page = Number.isInteger(pageRaw) && pageRaw > 0 ? Math.min(pageRaw, 10000) : 1;
const offset = (page - 1) * page_size;

const leadRaw = clean(q.lead, 40).toLowerCase();
const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(leadRaw);
const lead_id = isUuid ? leadRaw : '';

const themeRaw = clean(q.theme, 10).toLowerCase();
const theme = ['light', 'dark'].includes(themeRaw) ? themeRaw : 'light';
const exportRaw = clean(q.export, 8).toLowerCase();
const downloadRaw = clean(q.download, 30).toLowerCase();
const download = ['leads_csv', 'leads_xlsx', 'leads_pdf', 'leads_json'].includes(downloadRaw) ? downloadRaw : '';
const export_all = ['1', 'true', 'yes', 'all'].includes(exportRaw) || Boolean(download);

let error_msg = '';
if (operationRaw && !operationMatched) error_msg = 'Operacion no permitida.';
else if (!allowedSelectors.includes(selector)) error_msg = 'Filtro no permitido.';
else if (!['AMBAS', 'KIA', 'HYUNDAI'].includes(marcaRaw)) error_msg = 'Marca no permitida.';
else if (dateRawDesde && !desde) error_msg = 'Fecha desde invalida. Usa YYYY-MM-DD.';
else if (dateRawHasta && !hasta) error_msg = 'Fecha hasta invalida. Usa YYYY-MM-DD.';
else if (desde && hasta && desde > hasta) error_msg = 'La fecha desde no puede ser posterior a la fecha hasta.';
else if (!estados.includes(estadoRaw) && estadoRaw) error_msg = 'Estado no permitido.';
else if (leadRaw && !isUuid) error_msg = 'Lead UUID invalido.';
else if (selector === 'telefonos' && requested.length && requested.some((value) => value.replace(/\D/g, '').length < 7)) error_msg = 'Cada telefono debe tener al menos 7 digitos.';
else if (selector === 'quicklink_ids' && requested.length && requested.some((value) => !/^\d{1,9}$/.test(value))) error_msg = 'Los QuickLink IDs deben ser numericos.';
else if (selector === 'lead_ids' && requested.length && requested.some((value) => !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value))) error_msg = 'Los lead_ids deben ser UUID validos.';
else if (['nombre', 'telefonos', 'quicklink_ids', 'lead_ids'].includes(selector) && !requested.length && !lead_id) error_msg = 'Indica un valor para el filtro seleccionado.';

return [{ json: {
