  mode: lead_id ? 'report' : 'list',
  k: TOKEN,
  operacion,
  action,
  selector,
  selector_type: selector,
  valores_raw: rawValues,
  requested_values: requested,
  brand: marca,
  marca_sel,
  estado,
  desde,
  hasta,
  page,
  page_size,
  offset,
  lead_id,
  theme,
  export_all,
  download,
  query_blocked: Boolean(error_msg),
  error_msg,
} }];

const cfg = $('Preparar Consulta').first().json;
