  return `<span class="badge state ${cls}">${esc(value)}</span>`;
};
const statCard = (label, value, hint, cls = '') => `<div class="stat ${cls}"><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(hint || '')}</small></div>`;
const barList = (title, rows, totalValue) => {
  const body = arrayRows(rows).slice(0, 8).map((r) => {
