const csvEscape = (v) => '"' + String(v ?? '').replace(/\r?\n/g, ' ').replace(/"/g, '""') + '"';
const csvFromRows = (rows) => {
  const safeRows = rows.length ? rows : [{ info: 'Sin datos' }];
  const keys = Object.keys(safeRows[0] || { info: '' });
  return String.fromCharCode(65279) + [keys.join(';')].concat(safeRows.map((r) => keys.map((key) => csvEscape(r[key])).join(';'))).join(String.fromCharCode(10));
};
const xmlEsc = (v) => String(v ?? '').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g, ' ').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const sheetXml = (name, rows) => {
  const safeRows = rows.length ? rows : [{ info: 'Sin datos' }];
  const keys = Object.keys(safeRows[0] || { info: '' });
  const header = '<Row>' + keys.map((key) => '<Cell><Data ss:Type="String">' + xmlEsc(key) + '</Data></Cell>').join('') + '</Row>';
  const body = safeRows.map((row) => '<Row>' + keys.map((key) => {
    const raw = row[key];
    const str = String(raw ?? '');
    const n = Number(str);
    const numeric = str !== '' && Number.isFinite(n) && str.trim() === String(n);
    return '<Cell><Data ss:Type="' + (numeric ? 'Number' : 'String') + '">' + xmlEsc(str) + '</Data></Cell>';
  }).join('') + '</Row>').join('');
  return '<Worksheet ss:Name="' + xmlEsc(String(name || 'Sheet').slice(0, 31)) + '"><Table>' + header + body + '</Table></Worksheet>';
};
const buildExcelXml = (payload) => {
