};
const asciiClean = (v) => String(v ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^\x20-\x7e]/g, ' ').replace(/\s+/g, ' ').trim();
const pdfEsc = (v) => asciiClean(v).replace(/\\/g, '\\\\').replace(/\(/g, '\\(').replace(/\)/g, '\\)');
const fixed = (v, width) => {
  const s = asciiClean(v);
  return (s.length > width ? s.slice(0, Math.max(1, width - 1)) + '~' : s).padEnd(width, ' ');
};
const buildLeadsPdf = (payload) => {
  const rows = arrayRows(payload.export_leads);
  const pagination = payload.pagination || {};
  const filters = payload.filters || {};
  const filtersText = Object.keys(filters).map((key) => key + '=' + (filters[key] || 'todos')).join(' | ');
  const lines = [
    'CRIS09 Ops Console - Export leads',
    'Generado: ' + new Date().toISOString(),
    'Total filtro: ' + (pagination.total || 0) + ' | Exportados: ' + rows.length + (pagination.export_capped ? ' | limitado' : ''),
    'Filtros: ' + (filtersText || 'sin filtros'),
    '',
    fixed('QLID', 8) + fixed('Marca', 10) + fixed('Estado', 18) + fixed('Cliente', 34) + fixed('Telefono', 16) + fixed('Modelo', 26),
    '-'.repeat(112),
  ];
  rows.forEach((lead) => {
    lines.push(fixed(lead.quicklink_id, 8) + fixed(lead.marca, 10) + fixed(lead.estado_agente, 18) + fixed(lead.nombre_cliente, 34) + fixed(lead.telefono_agente || lead.telefono_1, 16) + fixed(lead.modelo, 26));
  });
  if (!rows.length) lines.push('Sin datos.');
  const objects = [null];
  const add = (body) => { objects.push(body); return objects.length - 1; };
  add('');
  add('');
  add('<< /Type /Font /Subtype /Type1 /BaseFont /Courier >>');
  const pageIds = [];
  const perPage = 44;
  const pageCountPdf = Math.max(1, Math.ceil(lines.length / perPage));
  const text = (x, y, size, value) => 'BT /F1 ' + size + ' Tf ' + x + ' ' + y + ' Td (' + pdfEsc(value) + ') Tj ET\n';
  for (let pageIndex = 0; pageIndex < pageCountPdf; pageIndex += 1) {
    let stream = '';
    stream += text(32, 560, 11, 'CRIS09 Ops Console');
    const slice = lines.slice(pageIndex * perPage, (pageIndex + 1) * perPage);
    let y = 540;
    slice.forEach((line) => { stream += text(32, y, 7, line); y -= 11; });
    stream += text(748, 24, 7, 'Pagina ' + (pageIndex + 1) + ' / ' + pageCountPdf);
    const contentId = add('<< /Length ' + stream.length + ' >>\nstream\n' + stream + 'endstream');
    const pageId = add('<< /Type /Page /Parent 2 0 R /MediaBox [0 0 842 595] /Resources << /Font << /F1 3 0 R >> >> /Contents ' + contentId + ' 0 R >>');
    pageIds.push(pageId);
  }
  objects[1] = '<< /Type /Catalog /Pages 2 0 R >>';
  objects[2] = '<< /Type /Pages /Kids [' + pageIds.map((id) => id + ' 0 R').join(' ') + '] /Count ' + pageIds.length + ' >>';
  let pdf = '%PDF-1.4\n% CRIS09\n';
  const offsets = [0];
  for (let i = 1; i < objects.length; i += 1) { offsets[i] = pdf.length; pdf += i + ' 0 obj\n' + objects[i] + '\nendobj\n'; }
  const xref = pdf.length;
  pdf += 'xref\n0 ' + objects.length + '\n0000000000 65535 f \n';
  for (let i = 1; i < objects.length; i += 1) pdf += String(offsets[i]).padStart(10, '0') + ' 00000 n \n';
  pdf += 'trailer\n<< /Size ' + objects.length + ' /Root 1 0 R >>\nstartxref\n' + xref + '\n%%EOF\n';
  return pdf;
};
const exportStamp = () => new Date().toISOString().slice(0, 10);
const safeFilename = (v) => (String(v || 'cris09-export').replace(/[^a-z0-9._-]+/gi, '-').replace(/^-+|-+$/g, '').slice(0, 140) || 'cris09-export');
const buildDirectExport = (payload) => {
  const action = payload && payload.download_action;
  if (!['leads_csv', 'leads_xlsx', 'leads_pdf', 'leads_json'].includes(action)) return null;
  const rows = exportRowsFor(payload.export_leads || []);
  const suffix = payload.pagination && payload.pagination.export_capped ? '-limitado' : '';
  const base = safeFilename('cris09-leads-' + exportStamp() + suffix);
  if (action === 'leads_csv') return { body: csvFromRows(rows), contentType: 'text/csv; charset=utf-8', filename: base + '.csv' };
  if (action === 'leads_json') return { body: JSON.stringify(payload, null, 2), contentType: 'application/json; charset=utf-8', filename: base + '.json' };
  if (action === 'leads_xlsx') return { body: buildExcelXml(payload), contentType: 'application/vnd.ms-excel; charset=utf-8', filename: base + '.xls' };
  if (action === 'leads_pdf') return { body: buildLeadsPdf(payload), contentType: 'application/pdf', filename: base + '.pdf' };
  return null;
};

