ms:flex-start;justify-content:space-between;gap:12px;margin-bottom:10px}.section-title p{margin:3px 0 0;color:var(--muted)}.barrow{padding:8px 0;border-top:1px solid var(--line)}.barrow:first-of-type{border-top:0}.barrow div{display:flex;justify-content:space-between;gap:12px}.barrow span{color:var(--muted)}.barrow i{display:block;height:5px;margin-top:5px;background:var(--hard);border-radius:999px}.filters{display:grid;grid-template-columns:minmax(220px,1.4fr) minmax(150px,.8fr) minmax(150px,.8fr) minmax(150px,.8fr) minmax(130px,.7fr) minmax(130px,.7fr) minmax(110px,.55fr) auto;gap:10px;align-items:end}.filters label{display:flex;flex-direction:column;gap:5px;color:var(--muted);font-weight:800}.filters input,.filters select{width:100%;min-height:36px;border:1px solid var(--line);border-radius:10px;background:var(--card);color:var(--ink);padding:7px 9px;font:inherit}.chips{display:flex;flex-wrap:wrap;gap:7px;margin-top:10px}.chip{display:inline-flex;gap:6px;align-items:center;border:1px solid var(--line);border-radius:999px;padding:5px 9px;color:var(--muted);background:var(--soft)}.chip b{color:var(--ink)}.exportbar{display:flex;flex-wrap:wrap;gap:8px;align-items:center;justify-content:space-between}.exportbar p{margin:0;color:var(--muted)}.warnline{color:var(--warn)!important;font-weight:800}.tablewrap{overflow:auto;border:1px solid var(--line);border-radius:12px}table{width:100%;border-collapse:separate;border-spacing:0;font-size:12px}th{position:sticky;top:0;background:var(--soft);color:var(--muted);text-align:left;text-transform:uppercase;font-size:10px;letter-spacing:.06em}th,td{padding:9px;border-bottom:1px solid var(--line);vertical-align:top}td small,.rowlink small{display:block;margin-top:3px;color:var(--muted)}.rowlink{color:var(--ink);text-decoration:none}.mono{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}.badge{display:inline-flex;min-height:22px;align-items:center;border-radius:999px;padding:3px 8px;font-weight:900;font-size:11px}.brand-kia{background:#ffe4e9;color:#8a1020}.brand-hyundai{background:#dff1fb;color:#075178}.brand-other{background:var(--soft);color:var(--muted)}.state-warn{background:#fff2cc;color:#854d0e}.state-work{background:#e5edff;color:#29448c}.state-good{background:#dcfce7;color:#166534}.state-bad{background:#fee2e2;color:#991b1b}.pager{display:flex;align-items:center;justify-content:space-between;gap:10px;color:var(--muted);margin:8px 0}.detailgrid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.kv{border:1px solid var(--line);border-radius:10px;padding:9px;background:var(--soft)}.kv span{display:block;color:var(--muted);font-size:10px;text-transform:uppercase;font-weight:900}.kv strong{display:block;margin-top:3px}.muted{color:var(--muted)}.okdot{color:var(--ok);font-weight:900}.foot{text-align:center;color:var(--muted);font-size:11px;margin-top:18px}
.dangerbtn{background:var(--bad);border-color:var(--bad);color:#fff}.picklead{display:inline-flex;padding:6px 9px;border:1px solid var(--line);border-radius:8px;color:var(--ink);font-weight:800;text-decoration:none}.qa-zone{border-color:color-mix(in srgb,var(--warn) 42%,var(--line));box-shadow:none}.qa-status{display:flex;gap:10px;align-items:center;margin:8px 0 12px;padding:10px 12px;border-radius:12px;border:1px solid var(--line);background:var(--soft)}.qa-status.ready b{color:var(--ok)}.qa-status.blocked b{color:var(--bad)}.qa-status span{color:var(--muted)}.qa-form{display:grid;grid-template-columns:minmax(220px,320px) minmax(220px,320px) auto;gap:10px;align-items:end}.qa-form label{display:grid;gap:5px;color:var(--muted);font-weight:900}.qa-form label small{font-weight:600}.qa-actions{display:flex;gap:8px;flex-wrap:wrap}
@media(max-width:1050px){.summary{grid-template-columns:repeat(4,1fr)}.grid2,.filters,.detailgrid,.qa-form{grid-template-columns:1fr}.hero{display:block}.toolbar{justify-content:flex-start;margin-top:10px}}
@media(max-width:760px){.wrap{padding:12px 8px 32px}.summary{grid-template-columns:1fr 1fr}.tablewrap{border:0;overflow:visible}table,thead,tbody,tr,td{display:block;width:100%}thead{display:none}tr{margin-bottom:10px;border:1px solid var(--line);border-radius:12px;padding:8px;background:var(--card)}td{display:flex;justify-content:space-between;gap:12px;border:0;padding:6px}td:before{content:attr(data-label);color:var(--muted);font-weight:900;text-transform:uppercase;font-size:10px}.pager{display:grid;grid-template-columns:1fr;text-align:center}.section-title{display:block}.section-title .linkbtn{margin-top:8px}.summary{grid-template-columns:1fr}.readonly{align-items:flex-start}}
</style></head><body><div class="wrap">
  <header class="hero"><div><h1>CRIS09 Ops Console</h1><p>Consulta, seleccion y prueba unitaria de leads. Buscar, paginar y exportar nunca ejecuta cambios.</p></div><nav class="toolbar"><a class="linkbtn" href="${esc(link({ theme: themeNext }))}">Tema ${esc(themeNext)}</a><a class="linkbtn" href="${esc(clearUrl)}">Limpiar filtros</a></nav></header>
  <section class="panel readonly"><b>BUSQUEDA SEGURA</b><span>Solo el formulario de prueba, con un lead exacto y confirmacion explicita, puede ejecutar una accion real.</span></section>
  ${cfg.error_msg ? `<section class="panel readonly"><b>VALIDACION</b><span>${esc(cfg.error_msg)}</span></section>` : ''}
  <section class="summary">
    ${statCard('Filtrados', num(total), `de ${num(baseTotal)} en base`)}
    ${statCard('Pendientes', num(kpis.pendientes), `${pct(kpis.pendientes, total)}%`, 'accent-warn')}
    ${statCard('En gestion', num(kpis.en_gestion), `${pct(kpis.en_gestion, total)}%`, 'accent-info')}
    ${statCard('Rezagados', num(kpis.rezagados), `${pct(kpis.rezagados, total)}%`, 'accent-bad')}
    ${statCard('Confirmadas AI', num(kpis.confirmadas_ai), `${pct(kpis.confirmadas_ai, total)}%`, 'accent-ok')}
    ${statCard('Con conv', num(kpis.con_conversacion), `${pct(kpis.con_conversacion, total)}%`, 'accent-hyundai')}
    ${statCard('Sin conv', num(kpis.sin_conversacion), 'requiere revision', 'accent-kia')}
    ${statCard('No reportados QL', num(kpis.no_reportados_ql), 'pendiente cierre', 'accent-info')}
  </section>
  <section class="panel">
    <form method="GET" action="">
      <input type="hidden" name="k" value="${esc(cfg.k)}"><input type="hidden" name="theme" value="${esc(cfg.theme || 'light')}"><input type="hidden" name="page" value="1">
      <div class="filters">
        <label>Valor<input name="valores" value="${esc(cfg.valores_raw || '')}" placeholder="nombre, telefono, QL ID o UUID"></label>
        <label>Filtro<select name="selector">${SELECTOR_OPTS.map(([v, l]) => opt(v, l, cfg.selector || 'smart')).join('')}</select></label>
        <label>Marca<select name="marca">${MARCAS.map((m) => opt(m, m, cfg.marca_sel || 'AMBAS')).join('')}</select></label>
        <label>Estado<select name="estado">${ESTADOS.map((e) => opt(e, e || 'Todos', cfg.estado || '')).join('')}</select></label>
        <label>Desde<input type="date" name="desde" value="${esc(cfg.desde || '')}"></label>
        <label>Hasta<input type="date" name="hasta" value="${esc(cfg.hasta || '')}"></label>
        <label>Page size<select name="page_size">${[25,50,100,250].map((n) => opt(String(n), String(n), String(pageSize))).join('')}</select></label>
        <button class="primary" type="submit">Aplicar</button>
      </div>
      <label style="margin-top:10px;display:block;color:var(--muted);font-weight:800">Accion observada<select name="operacion" style="margin-top:5px;width:100%;max-width:360px;min-height:36px;border:1px solid var(--line);border-radius:10px;background:var(--card);color:var(--ink);padding:7px 9px">${OPS.map((opName) => opt(opName, opName, cfg.operacion || 'Preview impacto')).join('')}</select></label>
    </form>
    <div class="chips">${chips}</div>
  </section>
  <section class="panel exportbar"><p>Exports directos server-side. No se insertan miles de filas en el HTML normal.</p><div class="toolbar"><a class="linkbtn" href="${esc(link({ download: 'leads_csv', export: 1 }))}">CSV</a><a class="linkbtn" href="${esc(link({ download: 'leads_xlsx', export: 1 }))}">Excel</a><a class="linkbtn" href="${esc(link({ download: 'leads_pdf', export: 1 }))}">PDF</a><a class="linkbtn" href="${esc(link({ download: 'leads_json', export: 1 }))}">JSON</a></div>${exportWarning}</section>
  ${controlledZone}
  ${detailHtml}
  <section class="grid2">${barList('Distribucion por marca', stats.by_brand, total)}${barList('Distribucion por estado', stats.by_state, total)}</section>
  ${tableHtml}
  <p class="foot">CRIS09 Ops Console · ${esc(new Date().toISOString())}</p>
<script>
function qaExpected(form) {
  const operation = String(form.querySelector('[name="Operacion"]')?.value || '');
  return operation === 'Enviar pendientes seleccionados' ? 'ENVIAR' : 'BORRAR';
}
function updateQaConfirmation(form) {
  const input = form.querySelector('[name="Confirmacion"]');
  if (input) input.placeholder = qaExpected(form);
}
function qaSubmit(form, event) {
  const submitter = event && event.submitter;
  const execute = submitter && submitter.dataset.execute === 'SI' ? 'SI' : 'NO';
  form.querySelector('[name="Ejecutar"]').value = execute;
  if (execute === 'SI') {
    const expected = qaExpected(form);
    const confirmation = form.querySelector('[name="Confirmacion"]');
    if (String(confirmation.value || '').trim().toUpperCase() !== expected) {
      window.alert('Escribe ' + expected + ' para confirmar la ejecucion real.');
      confirmation.focus();
      return false;
    }
    if (!window.confirm('Ejecutar una accion real sobre: ' + (form.dataset.leadLabel || 'el lead seleccionado') + '?')) return false;
  }
  const buttons = form.querySelectorAll('button');
  buttons.forEach((button) => { button.disabled = true; });
  if (execute === 'SI' && submitter) submitter.textContent = 'Ejecutando...';
  return true;
}
</script>
</div></body></html>`;

return [{ json: { page_html: html, response_content_type: 'text/html; charset=utf-8', response_disposition: 'inline', leads_count: leads.length, base_total: baseTotal, total, page, page_size: pageSize } }];

const q = $json.query || {};
const batchKey = String(q.batch_key || '').trim();
const token = String(q.token || '').trim();
if (!/^ops05:\d+$/.test(batchKey)) throw new Error('batch_key inválido');
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(token)) throw new Error('token inválido');
return [{ json: { batch_key: batchKey, token } }];

const status = $json.status || { found: false };
const data = JSON.parse(JSON.stringify(status));
const staleAfterMs = 10 * 60 * 1000;
const now = Date.now();

if (data.found && Array.isArray(data.dispatches)) {
  let stalePending = 0;
  data.dispatches = data.dispatches.map((dispatch) => {
    const messages = Array.isArray(dispatch.messages) ? dispatch.messages : [];
    const updatedAt = Date.parse(dispatch.updated_at || dispatch.created_at || '');
    const stale = dispatch.delivery_status === 'pending'
      && dispatch.intake_status === 'accepted'
      && messages.length === 0
      && Number.isFinite(updatedAt)
      && now - updatedAt > staleAfterMs;
    if (!stale) return dispatch;
    stalePending += 1;
    return {
      ...dispatch,
      delivery_status: 'stale_pending',
      stale_pending: true,
      stale_reason: 'accepted_without_meta_messages',
    };
  });
  data.totals = { ...(data.totals || {}), stale_pending: stalePending };
  if (stalePending > 0) {
    const open = data.dispatches.filter((dispatch) => !['delivered', 'read', 'failed', 'stale_pending'].includes(dispatch.delivery_status)).length;
    data.complete = open === 0;
    data.warning = 'stale_pending_without_meta_messages';
  }
}

return [{ json: data }];
